css:
.sl-gallery-chapters { padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-gallery-chapters .sl-container { max-width: 1140px; width: 100%; margin-inline: auto; }
.sl-gallery-chapters .sl-chapters-header { margin-bottom: 2.5rem; }
.sl-gallery-chapters .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.75rem, 3.5vw, 2.25rem); font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-gallery-chapters .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-gallery-chapters .sl-chapters-layout { display: flex; flex-direction: column; gap: 1.5rem; }
.sl-gallery-chapters .sl-chapters-media { flex: 1; border-radius: var(--smartlearn-radius, 1rem); overflow: hidden; background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); }
.sl-gallery-chapters .sl-media-ratio { position: relative; aspect-ratio: 16/9; width: 100%; }
.sl-gallery-chapters .sl-chapters-poster { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; transition: opacity 0.3s ease; }
.sl-gallery-chapters .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 72px; height: 72px; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25); cursor: pointer; transition: transform 0.2s ease, background-color 0.2s ease; z-index: 5; }
.sl-gallery-chapters .sl-play-overlay:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translate(-50%, -50%) scale(1.08); }
.sl-gallery-chapters .sl-play-overlay:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 3px; }
.sl-gallery-chapters .sl-close-video { position: absolute; top: 0.75rem; inset-inline-end: 0.75rem; z-index: 20; width: 44px; height: 44px; border-radius: 50%; border: none; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 1.35rem; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.sl-gallery-chapters .sl-close-video:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-chapters .sl-chapters-nav { display: flex; flex-direction: row; overflow-x: auto; gap: 1rem; padding-bottom: 0.75rem; scroll-snap-type: x mandatory; }
.sl-gallery-chapters .sl-chapter-item { position: relative; display: flex; align-items: center; gap: 1rem; padding: 1rem; background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 0.75rem); min-width: 260px; scroll-snap-align: start; transition: border-color 0.2s ease, background-color 0.2s ease; }
.sl-gallery-chapters .sl-chapter-item.sl-active { border-color: var(--smartlearn-primary); box-shadow: 0 4px 15px rgba(0, 0, 0, 0.06); }
.sl-gallery-chapters .sl-chapter-thumb { width: 80px; height: 60px; border-radius: 0.5rem; overflow: hidden; flex-shrink: 0; }
.sl-gallery-chapters .sl-chapter-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-chapters .sl-chapter-info { display: flex; flex-direction: column; min-width: 0; }
.sl-gallery-chapters .sl-chapter-num { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; color: var(--smartlearn-primary); margin-bottom: 0.25rem; }
.sl-gallery-chapters .sl-chapter-heading { margin: 0; font-size: 1rem; }
.sl-gallery-chapters .sl-chapter-btn { background: transparent; border: none; padding: 0; font-family: var(--smartlearn-heading-font, inherit); font-size: 1rem; font-weight: 600; color: var(--smartlearn-text); text-align: start; line-height: 1.4; cursor: pointer; }
.sl-gallery-chapters .sl-chapter-btn::after { content: ''; position: absolute; inset: 0; }
.sl-gallery-chapters .sl-chapter-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 4px; border-radius: 0.25rem; }
@media (min-width: 992px) { .sl-gallery-chapters .sl-chapters-layout { flex-direction: row; align-items: stretch; } .sl-gallery-chapters .sl-chapters-nav { flex-direction: column; overflow-x: visible; width: 350px; flex-shrink: 0; padding-bottom: 0; scroll-snap-type: none; } }
@media (prefers-reduced-motion: reduce) { .sl-gallery-chapters .sl-chapters-poster, .sl-gallery-chapters .sl-play-overlay, .sl-gallery-chapters .sl-chapter-item { transition: none; } .sl-gallery-chapters .sl-play-overlay:hover { transform: translate(-50%, -50%); } }

js:
(function() {
  function toSafeEmbedUrl(raw) {
    try {
      var u = new URL(raw, window.location.href);
      if (u.protocol !== 'https:') return '';
      var host = u.hostname.replace(/^www\./, '');
      if (host === 'youtu.be') {
        var id = u.pathname.split('/').filter(Boolean)[0];
        return id ? 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(id) + '?autoplay=1' : '';
      }
      if (host === 'youtube.com' || host === 'youtube-nocookie.com') {
        var vid = u.searchParams.get('v');
        if (!vid && u.pathname.indexOf('/embed/') === 0) vid = u.pathname.split('/')[2];
        return vid ? 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(vid) + '?autoplay=1' : '';
      }
      if (host === 'vimeo.com' || host === 'player.vimeo.com') {
        var parts = u.pathname.split('/').filter(Boolean);
        var vimeoId = parts[parts.length - 1];
        return /^\d+$/.test(vimeoId) ? 'https://player.vimeo.com/video/' + vimeoId + '?autoplay=1' : '';
      }
    } catch (e) {}
    return '';
  }
  var init = function() {
    document.querySelectorAll('.sl-gallery-chapters').forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var items = Array.prototype.slice.call(root.querySelectorAll('.sl-chapter-item'));
      var activeImg = root.querySelector('.sl-chapters-poster');
      var playBtn = root.querySelector('.sl-chapters-play-btn');
      var mediaArea = root.querySelector('.sl-media-ratio');
      if (!items.length || !activeImg || !playBtn || !mediaArea) return;
      var currentVideoUrl = '';
      var currentTitle = 'Chapter video';
      var clearVideo = function() {
        var existingIframe = mediaArea.querySelector('iframe');
        var existingClose = mediaArea.querySelector('.sl-close-video');
        if (existingIframe) existingIframe.remove();
        if (existingClose) existingClose.remove();
        activeImg.style.display = '';
        playBtn.style.display = '';
      };
      var selectChapter = function(item) {
        clearVideo();
        items.forEach(function(c) {
          c.classList.remove('sl-active');
          var b = c.querySelector('.sl-chapter-btn');
          if (b) b.setAttribute('aria-pressed', 'false');
        });
        item.classList.add('sl-active');
        var btn = item.querySelector('.sl-chapter-btn');
        if (btn) {
          btn.setAttribute('aria-pressed', 'true');
          currentVideoUrl = btn.getAttribute('data-video-url') || '';
          currentTitle = btn.textContent.trim() || 'Chapter video';
        }
        var thumb = item.querySelector('.sl-chapter-thumb img');
        if (thumb && thumb.getAttribute('src')) {
          activeImg.src = thumb.src;
          activeImg.alt = thumb.alt || currentTitle;
        }
      };
      items.forEach(function(item) {
        var btn = item.querySelector('.sl-chapter-btn');
        if (btn) btn.addEventListener('click', function() { selectChapter(item); });
      });
      var initial = root.querySelector('.sl-chapter-item.sl-active') || items[0];
      if (initial) selectChapter(initial);
      playBtn.addEventListener('click', function() {
        var safeUrl = toSafeEmbedUrl(currentVideoUrl);
        if (!safeUrl) return;
        clearVideo();
        activeImg.style.display = 'none';
        playBtn.style.display = 'none';
        var iframe = document.createElement('iframe');
        iframe.src = safeUrl;
        iframe.title = currentTitle;
        iframe.referrerPolicy = 'strict-origin-when-cross-origin';
        iframe.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;border:none;z-index:10;';
        iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
        iframe.setAttribute('allowfullscreen', 'true');
        var closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.className = 'sl-close-video';
        closeBtn.setAttribute('aria-label', 'Close video');
        closeBtn.textContent = '×';
        closeBtn.addEventListener('click', function() {
          clearVideo();
          playBtn.focus();
        });
        mediaArea.appendChild(iframe);
        mediaArea.appendChild(closeBtn);
        closeBtn.focus();
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
